describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 500, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 5.5, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 500, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("accepts valid brackets and overflow", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [
              { upToGrams: 500, costCents: 300 },
              { upToGrams: 1000, costCents: 500 },
            ],
            800,
          ),
      ).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 1000, costCents: 500 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 800 },
      ],
      1200,
    );

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 for cart with zero total weight", () => {
      const lines: CartLine[] = [
        { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 2 },
      ];
      expect(calc.computeShippingCents(lines, 200)).toBe(0);
    });

    it("selects correct bracket at lower boundary", () => {
      // weight = 500g → first sorted bracket (upToGrams=500, cost=300)
      expect(calc.computeShippingCents([makeLine("a", 500, 1)], 1000)).toBe(300);
    });

    it("selects correct bracket at exact boundary", () => {
      // weight = 1000g → second sorted bracket (upToGrams=1000, cost=500)
      expect(calc.computeShippingCents([makeLine("a", 1000, 1)], 1000)).toBe(500);
    });

    it("selects correct bracket between boundaries", () => {
      // weight = 750g → falls in (500, 1000] bracket → cost=500
      expect(calc.computeShippingCents([makeLine("a", 750, 1)], 1000)).toBe(500);
    });

    it("selects highest bracket at its boundary", () => {
      // weight = 2000g → (1000, 2000] → cost=800
      expect(calc.computeShippingCents([makeLine("a", 2000, 1)], 1000)).toBe(800);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      // weight = 2500g → overflow → 1200
      expect(calc.computeShippingCents([makeLine("a", 2500, 1)], 1000)).toBe(1200);
    });

    it("falls back to heaviest bracket cost when no overflow specified", () => {
      const calcNoOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 500 },
      ]);
      // weight = 5000g → no overflow set → uses last bracket cost = 500
      expect(
        calcNoOverflow.computeShippingCents([makeLine("a", 5000, 1)], 1000),
      ).toBe(500);
    });

    it("accumulates weight across multiple lines", () => {
      // 200*3 + 400*2 = 600 + 800 = 1400g → (1000, 2000] → 800
      const lines = [makeLine("a", 200, 3), makeLine("b", 400, 2)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(800);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";

const product = (overrides: Partial<Product> = {}): Product => ({
  id: "p1",
  name: "Widget",
  unitPriceCents: 1000,
  ...overrides,
});

describe("Cart", () => {
  describe("add", () => {
    it("adds a product to an empty cart", () => {
      const cart = new Cart();
      cart.add(product(), 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantities when same product added again", () => {
      const cart = new Cart();
      cart.add(product(), 2);
      cart.add(product(), 3);
      expect(cart.itemCount).toBe(5);
    });

    it("throws for non-positive quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(product(), 0)).toThrow(RangeError);
      expect(() => cart.add(product(), -1)).toThrow(RangeError);
    });

    it("throws for non-integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(product(), 1.5)).toThrow(RangeError);
    });

    it("throws for negative unitPriceCents", () => {
      const cart = new Cart();
      expect(() => cart.add(product({ unitPriceCents: -1 }), 1)).toThrow(
        RangeError,
      );
    });
  });

  describe("remove", () => {
    it("removes an existing product and returns true", () => {
      const cart = new Cart();
      cart.add(product(), 1);
      expect(cart.remove("p1")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product id", () => {
      const cart = new Cart();
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity of existing product", () => {
      const cart = new Cart();
      cart.add(product(), 5);
      cart.updateQuantity("p1", 3);
      expect(cart.itemCount).toBe(3);
    });

    it("removes product when quantity set to 0", () => {
      const cart = new Cart();
      cart.add(product(), 5);
      cart.updateQuantity("p1", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for unknown product", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("unknown", 5)).toThrow(
        "Product unknown is not in the cart",
      );
    });

    it("throws for negative quantity", () => {
      const cart = new Cart();
      cart.add(product(), 1);
      expect(() => cart.updateQuantity("p1", -1)).toThrow(RangeError);
    });

    it("throws for non-integer quantity", () => {
      const cart = new Cart();
      cart.add(product(), 1);
      expect(() => cart.updateQuantity("p1", 2.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("removes all items", () => {
      const cart = new Cart();
      cart.add(product({ id: "a" }), 1);
      cart.add(product({ id: "b" }), 2);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy of lines", () => {
      const cart = new Cart();
      const p = product();
      cart.add(p, 2);
      const snap = cart.snapshot();
      expect(snap).toHaveLength(1);
      expect(snap[0].product.id).toBe("p1");
      expect(snap[0].quantity).toBe(2);
      // mutating snapshot does not affect cart
      (snap[0] as { quantity: number }).quantity = 99;
      expect(cart.itemCount).toBe(2);
    });
  });

  describe("totals (pricing pipeline)", () => {
    it("computes subtotal as sum of unitPriceCents * quantity", () => {
      const cart = new Cart();
      cart.add(product({ id: "a", unitPriceCents: 500 }), 2);
      cart.add(product({ id: "b", unitPriceCents: 300 }), 3);
      const t = cart.totals();
      expect(t.subtotalCents).toBe(1900); // 500*2 + 300*3
    });

    it("applies discount then tax on discounted subtotal", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const tax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(80),
      };
      const cart = new Cart({ discountPolicy: discount, taxCalculator: tax });
      cart.add(product({ unitPriceCents: 1000 }), 1);
      const t = cart.totals();

      expect(t.subtotalCents).toBe(1000);
      expect(t.discountCents).toBe(200);
      // tax receives discounted subtotal = 1000 - 200 = 800
      expect(tax.computeTaxCents).toHaveBeenCalledWith(800, "US");
      expect(t.taxCents).toBe(80);
    });

    it("clamps discount to [0, subtotal]", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(5000),
      };
      const cart = new Cart({ discountPolicy: discount });
      cart.add(product({ unitPriceCents: 1000 }), 1);
      const t = cart.totals();
      expect(t.discountCents).toBe(1000); // clamped to subtotal
    });

    it("clamps negative discount to 0", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ discountPolicy: discount });
      cart.add(product({ unitPriceCents: 1000 }), 1);
      const t = cart.totals();
      expect(t.discountCents).toBe(0);
    });

    it("shipping receives discounted subtotal and lines", () => {
      const shipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };
      const discount: DiscountPolicy = {
        computeDiscountCents: () => 300,
      };
      const cart = new Cart({
        discountPolicy: discount,
        shippingCalculator: shipping,
      });
      cart.add(product({ unitPriceCents: 1000 }), 1);
      const t = cart.totals();
      // discounted subtotal = 1000-300=700
      expect(shipping.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        700,
      );
      expect(t.shippingCents).toBe(500);
    });

    it("totalCents = discountedSubtotal + tax + shipping", () => {
      const discount: DiscountPolicy = { computeDiscountCents: () => 100 };
      const tax: TaxCalculator = { computeTaxCents: () => 50 };
      const shipping: ShippingCalculator = {
        computeShippingCents: () => 200,
      };
      const cart = new Cart({
        discountPolicy: discount,
        taxCalculator: tax,
        shippingCalculator: shipping,
      });
      cart.add(product({ unitPriceCents: 1000 }), 1);
      const t = cart.totals();
      // subtotal=1000, discount=100, discounted=900, tax=50, shipping=200
      expect(t.totalCents).toBe(900 + 50 + 200);
    });

    it("uses provided region for tax calculation", () => {
      const tax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(0),
      };
      const cart = new Cart({ taxCalculator: tax, region: "FR" });
      cart.add(product(), 1);
      cart.totals();
      expect(tax.computeTaxCents).toHaveBeenCalledWith(expect.any(Number), "FR");
    });

    it("empty cart returns all zeros", () => {
      const cart = new Cart();
      const t = cart.totals();
      expect(t).toEqual({
        subtotalCents: 0,
        discountCents: 0,
        taxCents: 0,
        shippingCents: 0,
        totalCents: 0,
      });
    });

    it("clamps negative tax to 0", () => {
      const tax: TaxCalculator = { computeTaxCents: () => -50 };
      const cart = new Cart({ taxCalculator: tax });
      cart.add(product(), 1);
      expect(cart.totals().taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const shipping: ShippingCalculator = {
        computeShippingCents: () => -100,
      };
      const cart = new Cart({ shippingCalculator: shipping });
      cart.add(product(), 1);
      expect(cart.totals().shippingCents).toBe(0);
    });
  });
});

