import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([
    [0, 0],
    [1000, 0],
    [999999, 0],
    [-500, 0],
  ])("computeDiscountCents(%i) returns %i", (subtotal, expected) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(expected);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([[-1], [101], [NaN], [Infinity], [-Infinity]])(
      "rejects invalid percent: %s",
      (percent) => {
        expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
      },
    );

    it.each([[0], [50], [100]])("accepts valid percent: %s", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it.each([
      [10, 1000, 100],
      [50, 1000, 500],
      [100, 1000, 1000],
      [0, 1000, 0],
      [33, 100, 33],
      [33, 101, 33], // floors: 101*33/100 = 33.33 → 33
      [15, 999, 149], // floors: 999*15/100 = 149.85 → 149
    ])(
      "%i%% of %i cents = %i cents (floors)",
      (percent, subtotal, expected) => {
        const p = new PercentageDiscountPolicy(percent);
        expect(p.computeDiscountCents(subtotal)).toBe(expected);
      },
    );

    it("returns 0 for zero subtotal", () => {
      const p = new PercentageDiscountPolicy(50);
      expect(p.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const p = new PercentageDiscountPolicy(50);
      expect(p.computeDiscountCents(-100)).toBe(0);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([[-1], [-100], [1.5], [NaN]])(
      "rejects invalid amountCents: %s",
      (amount) => {
        expect(() => new FixedAmountDiscountPolicy(amount)).toThrow(RangeError);
      },
    );

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns 0 when subtotal is zero", () => {
      const p = new FixedAmountDiscountPolicy(500);
      expect(p.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 when subtotal is negative", () => {
      const p = new FixedAmountDiscountPolicy(500);
      expect(p.computeDiscountCents(-100)).toBe(0);
    });

    it("returns amountCents when subtotal exceeds it", () => {
      const p = new FixedAmountDiscountPolicy(500);
      expect(p.computeDiscountCents(1000)).toBe(500);
    });

    it("caps at subtotal when amountCents exceeds subtotal", () => {
      const p = new FixedAmountDiscountPolicy(1500);
      expect(p.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns exact subtotal when equal", () => {
      const p = new FixedAmountDiscountPolicy(1000);
      expect(p.computeDiscountCents(1000)).toBe(1000);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policies array", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from multiple policies against original subtotal", () => {
      const p = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 1000 = 100, plus fixed 200 = 300
      expect(p.computeDiscountCents(1000)).toBe(300);
    });

    it("can exceed subtotal (caller clamps)", () => {
      const p = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(600), new FixedAmountDiscountPolicy(600)],
        "sum",
      );
      // Each returns min(600, 1000)=600, sum=1200 > 1000 (Cart clamps)
      expect(p.computeDiscountCents(1000)).toBe(1200);
    });

    it("returns 0 for zero subtotal", () => {
      const p = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "sum",
      );
      expect(p.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const p = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "sum",
      );
      expect(p.computeDiscountCents(-100)).toBe(0);
    });

    it("clamps negative policy returns to 0 before summing", () => {
      const negativePol = { computeDiscountCents: () => -50 };
      const p = new CompositeDiscountPolicy(
        [negativePol, new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      // max(0, -50) + max(0, 100) = 0 + 100 = 100
      expect(p.computeDiscountCents(1000)).toBe(100);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const p = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new PercentageDiscountPolicy(50)],
        "chain",
      );
      // First: 50% of 1000 = 500. Remaining = 500.
      // Second: 50% of 500 = 250. Remaining = 250.
      // Total discount = 750
      expect(p.computeDiscountCents(1000)).toBe(750);
    });

    it("ordering affects result", () => {
      const p1 = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(300), new PercentageDiscountPolicy(50)],
        "chain",
      );
      // First: min(300, 1000)=300. Remaining=700.
      // Second: 50% of 700 = 350. Remaining=350.
      // Total = 650
      expect(p1.computeDiscountCents(1000)).toBe(650);

      const p2 = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new FixedAmountDiscountPolicy(300)],
        "chain",
      );
      // First: 50% of 1000=500. Remaining=500.
      // Second: min(300, 500)=300. Remaining=200.
      // Total = 800
      expect(p2.computeDiscountCents(1000)).toBe(800);
    });

    it("returns 0 for zero subtotal", () => {
      const p = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "chain",
      );
      expect(p.computeDiscountCents(0)).toBe(0);
    });

    it("stops reducing past zero remaining", () => {
      const p = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(600), new FixedAmountDiscountPolicy(600)],
        "chain",
      );
      // First: min(600, 1000)=600. Remaining=400.
      // Second: min(600, 400)=400. Remaining=0.
      // Total = 1000
      expect(p.computeDiscountCents(1000)).toBe(1000);
    });
  });
});

