    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 for cart with zero total weight", () => {
      const lines: CartLine[] = [
        { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 2 },
      ];
      expect(calc.computeShippingCents(lines, 200)).toBe(0);
    });

    it("selects correct bracket at lower boundary", () => {
      // weight = 500g → first sorted bracket (upToGrams=500, cost=300)
      expect(calc.computeShippingCents([makeLine("a", 500, 1)], 1000)).toBe(300);
    });

    it("selects correct bracket at exact boundary", () => {
      // weight = 1000g → second sorted bracket (upToGrams=1000, cost=500)
      expect(calc.computeShippingCents([makeLine("a", 1000, 1)], 1000)).toBe(500);
    });

    it("selects correct bracket between boundaries", () => {
      // weight = 750g → falls in (500, 1000] bracket → cost=500
      expect(calc.computeShippingCents([makeLine("a", 750, 1)], 1000)).toBe(500);
    });

    it("selects highest bracket at its boundary", () => {
      // weight = 2000g → (1000, 2000] → cost=800
      expect(calc.computeShippingCents([makeLine("a", 2000, 1)], 1000)).toBe(800);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      // weight = 2500g → overflow → 1200
      expect(calc.computeShippingCents([makeLine("a", 2500, 1)], 1000)).toBe(1200);
    });

    it("falls back to heaviest bracket cost when no overflow specified", () => {
      const calcNoOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 500 },
      ]);
      // weight = 5000g → no overflow set → uses last bracket cost = 500
      expect(
        calcNoOverflow.computeShippingCents([makeLine("a", 5000, 1)], 1000),
      ).toBe(500);
    });

    it("accumulates weight across multiple lines", () => {
      // 200*3 + 400*2 = 600 + 800 = 1400g → (1000, 2000] → 800
      const lines = [makeLine("a", 200, 3), makeLine("b", 400, 2)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(800);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
