toolArgs.file_text:
import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError, refreshPrices } from "../src/inventory.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { Product, CartLine } from "../src/product.ts";
import { PercentageDiscountPolicy } from "../src/pricing.ts";
import { FlatShippingCalculator } from "../src/shipping.ts";

const product = (overrides: Partial<Product> = {}): Product => ({
  id: "p1",
  name: "Widget",
  unitPriceCents: 1000,
  ...overrides,
});

describe("refreshPrices", () => {
  it("updates prices from fetcher", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const lines: CartLine[] = [{ product: product(), quantity: 2 }];
    const result = await refreshPrices(lines, fetcher);
    expect(result[0].product.unitPriceCents).toBe(1500);
    expect(result[0].quantity).toBe(2);
    expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("p1");
  });

  it("throws for invalid price (non-integer)", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(9.99),
    };
    const lines: CartLine[] = [{ product: product(), quantity: 1 }];
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("throws for negative price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-100),
    };
    const lines: CartLine[] = [{ product: product(), quantity: 1 }];
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("propagates fetcher rejection", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("service down")),
    };
    const lines: CartLine[] = [{ product: product(), quantity: 1 }];
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow("service down");
  });

  it("returns empty array for empty lines", async () => {
    const fetcher: PriceFetcher = { fetchPriceCents: vi.fn() };
    const result = await refreshPrices([], fetcher);
    expect(result).toEqual([]);
    expect(fetcher.fetchPriceCents).not.toHaveBeenCalled();
  });
});

describe("Cart.checkout()", () => {
  describe("price refresh", () => {
    it("refreshes prices before computing totals", async () => {
      const cart = new Cart();
      cart.add(product({ unitPriceCents: 1000 }), 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(2000),
      };
      const result = await cart.checkout({ priceFetcher });
      expect(result.lines[0].product.unitPriceCents).toBe(2000);
      expect(result.totals.subtotalCents).toBe(2000);
    });
  });

  describe("inventory check", () => {
    it("passes when inventory is available", async () => {
      const cart = new Cart();
      cart.add(product(), 2);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const result = await cart.checkout({ inventoryChecker });
      expect(result.totals.subtotalCents).toBe(2000);
      expect(inventoryChecker.check).toHaveBeenCalledWith("p1", 2);
    });

    it("throws InventoryError when item is unavailable", async () => {
      const cart = new Cart();
      cart.add(product(), 3);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 1,
          reason: "low stock",
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InventoryError;
        expect(err.productId).toBe("p1");
        expect(err.requested).toBe(3);
        expect(err.available).toBe(1);
        expect(err.message).toBe("low stock");
        expect(err.name).toBe("InventoryError");
      }
    });

    it("throws InventoryError on partial-stock denial", async () => {
      const cart = new Cart();
      cart.add(product(), 10);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 5,
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InventoryError;
        expect(err.productId).toBe("p1");
        expect(err.requested).toBe(10);
        expect(err.available).toBe(5);
      }
    });

    it("generates default message when reason is not provided", async () => {
      const cart = new Cart();
      cart.add(product(), 5);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 2,
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (e) {
        const err = e as InventoryError;
        expect(err.message).toContain("insufficient stock");
        expect(err.message).toContain("p1");
      }
    });
  });

  describe("async tax provider", () => {
    it("uses async tax provider for totals", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(10),
        shippingCalculator: new FlatShippingCalculator(500),
      });
      cart.add(product({ unitPriceCents: 1000 }), 2);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const result = await cart.checkout({ asyncTaxProvider });
      // subtotal=2000, discount=10%=200, discounted=1800
      // tax=0.1*1800=180, shipping=500
      expect(result.totals.subtotalCents).toBe(2000);
      expect(result.totals.discountCents).toBe(200);
      expect(result.totals.taxCents).toBe(180);
      expect(result.totals.shippingCents).toBe(500);
      expect(result.totals.totalCents).toBe(1800 + 180 + 500);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
    });

    it("propagates async tax provider errors", async () => {
      const cart = new Cart();
      cart.add(product(), 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("rate service down")),
      };
      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        "rate service down",
      );
    });
  });

  describe("combined collaborators", () => {
    it("runs full pipeline: price refresh → inventory → async tax", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(20),
        shippingCalculator: new FlatShippingCalculator(300, 5000),
        region: "US-CA",
      });
      cart.add(product({ id: "a", unitPriceCents: 500 }), 2);
      cart.add(product({ id: "b", unitPriceCents: 700 }), 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi
          .fn()
          .mockResolvedValueOnce(600) // product a updated to 600
          .mockResolvedValueOnce(800), // product b updated to 800
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.0875),
      };

      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });

      // After price refresh: a=600*2=1200, b=800*1=800 → subtotal=2000
      expect(result.totals.subtotalCents).toBe(2000);
      // Discount: 20% of 2000 = 400
      expect(result.totals.discountCents).toBe(400);
      // Discounted: 2000-400 = 1600
      // Tax: floor(1600 * 0.0875) = floor(140) = 140
      expect(result.totals.taxCents).toBe(140);
      // Shipping: discounted=1600 < 5000 threshold → 300
      expect(result.totals.shippingCents).toBe(300);
      expect(result.totals.totalCents).toBe(1600 + 140 + 300);

      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
      expect(inventoryChecker.check).toHaveBeenCalledTimes(2);
    });

    it("checkout without collaborators returns sync totals", async () => {
      const cart = new Cart();
      cart.add(product({ unitPriceCents: 500 }), 4);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(2000);
      expect(result.totals.totalCents).toBe(2000);
    });
  });
});

describe("InventoryError", () => {
  it("exposes correct properties", () => {
    const err = new InventoryError("out of stock", "prod-1", 5, 2);
    expect(err.name).toBe("InventoryError");
    expect(err.message).toBe("out of stock");
    expect(err.productId).toBe("prod-1");
    expect(err.requested).toBe(5);
    expect(err.available).toBe(2);
    expect(err).toBeInstanceOf(Error);
  });

  it("supports undefined available", () => {
    const err = new InventoryError("gone", "prod-2", 3, undefined);
    expect(err.available).toBeUndefined();
  });
});

